package testutil

import (
	"crypto/ed25519"
	"encoding/base64"
)

// Deterministic static Ed25519 public keys for testing
const (
	TestPublicKeyBase64  = "+DMzfGXQV/FDlx6Eh/jMw5iQYfxiBZDkTTumAQ67PnQ="
	TestPublicKey2Base64 = "9FksJhqlvdF5S0wm6pLQrkp6qRjy4PZDrZUsKlTzycE="
)

// GetTestPublicKey returns the primary decoded Ed25519 public key for test verification.
func GetTestPublicKey() ed25519.PublicKey {
	b, _ := base64.StdEncoding.DecodeString(TestPublicKeyBase64)
	return ed25519.PublicKey(b)
}

// GetTestPublicKey2 returns the secondary decoded Ed25519 public key for multi-key test verification.
func GetTestPublicKey2() ed25519.PublicKey {
	b, _ := base64.StdEncoding.DecodeString(TestPublicKey2Base64)
	return ed25519.PublicKey(b)
}

